db.accounts??=[];db.breaks??=[];db.points??=[];db.ruleVersions??=[];db.rules??={enabled:false,breakMinutes:15,maxBreaks:2,graceMinutes:0,redPerOverrun:1,greenToCancel:1,autoGreen:false,version:0};
navs.push(['accounts','♙','الحسابات والأكسس'],['branch-access','⌖','أكسس حضور الفروع'],['manual','✎','التسجيل اليدوي'],['breaks','☕','البريكات'],['score','◉','التحفيز والجزاءات'],['rules','⚙','إعدادات اللائحة'],['reports','▥','التقارير'] );
const operationRender=render, defaultAdminAdd=$('#add').onclick;let reportFilter={from:'',to:'',employee:'',branch:''};let scoreEmployee='';
const accessLabels={view_live:'رؤية حالة الموظفين',view_contact:'عرض بيانات الاتصال',view_history:'عرض سجل الموظف',view_breaks:'عرض البريكات',view_reports:'عرض التقارير',export_reports:'تصدير وطباعة التقارير',manual_in:'إضافة حضور',manual_out:'إضافة انصراف',manual_edit:'تصحيح يوم قديم',manual_break:'إدارة بريك يدوي',approve_requests:'قبول ورفض الطلبات',create_employee:'إنشاء موظف',create_manager:'إنشاء مدير',edit_employee:'تعديل وأرشفة موظف',manage_access:'إدارة الأكسس',view_salary:'عرض الرواتب',edit_salary:'تعديل الرواتب',manage_points:'إضافة وإلغاء نقاط',manage_rules:'تعديل اللائحة'};
function allEmployees(){return [...db.staff,...db.archived]}
function staffOptions(name='employee',withAll=false,value=''){return `<select name="${name}" id="${name}">${withAll?'<option value="">كل الموظفين</option>':''}${allEmployees().map(s=>`<option value="${s.id}" ${String(value)===String(s.id)?'selected':''}>${esc(s.name)}</option>`).join('')}</select>`}
function activePunch(id){return db.punches.find(p=>p.employeeId===id&&!p.out)}
function activeBreak(id){return db.breaks.find(b=>b.employeeId===id&&!b.end)}
function breakDuration(b,now=Date.now()){return Math.max(0,((b.end?new Date(b.end).getTime():now)-new Date(b.start).getTime())/60000)}
function breakOverrun(b,now=Date.now()){return Math.max(0,breakDuration(b,now)-b.allowedMinutes-(b.rule.graceMinutes||0))}
function scoreSummary(id){const entries=db.points.filter(p=>p.employeeId===id&&!p.voidedAt);let green=entries.filter(p=>p.color==='green').reduce((a,p)=>a+p.amount,0),red=entries.filter(p=>p.color==='red').reduce((a,p)=>a+p.amount,0);const ratio=db.rules.greenToCancel||1,cancelled=Math.min(red,Math.floor(green/ratio));return {green,red,cancelled,remaining:red-cancelled,available:green-cancelled*ratio,ratio}}
function addPoint({employeeId,color,amount,reason,source,at=new Date().toISOString(),ruleVersion=db.rules.version}){if(!Number.isInteger(amount)||amount<1||!reason?.trim())throw Error('العدد لازم يكون صحيح وموجب، مع سبب واضح');if(source&&db.points.some(p=>p.source===source))return false;db.points.push({id:crypto.randomUUID(),employeeId,color,amount,reason:reason.trim(),source,at,ruleVersion});return true}
function settleBreak(b){if(!b.end||b.settled)return;b.settled=true;const over=breakOverrun(b);if(b.rule.enabled&&over>0)addPoint({employeeId:b.employeeId,color:'red',amount:b.rule.redPerOverrun,reason:`تجاوز بريك ${Math.ceil(over)} دقيقة — لائحة v${b.rule.version}`,source:'break-red:'+b.id,ruleVersion:b.rule.version});if(b.rule.enabled&&b.rule.autoGreen&&over===0&&b.source!=='manual'){const day=cairoDay(b.start);addPoint({employeeId:b.employeeId,color:'green',amount:1,reason:'الالتزام بموعد البريك — نقطة واحدة كحد أقصى في اليوم',source:'break-green:'+b.employeeId+':'+day,ruleVersion:b.rule.version})}}
function startBreak(id,source='employee',reason=''){const p=activePunch(id);if(!p)throw Error('سجّل حضور الأول قبل بدء البريك');if(activeBreak(id))throw Error('يوجد بريك مفتوح بالفعل');const count=db.breaks.filter(b=>b.punchId===p.id).length;if(count>=db.rules.maxBreaks)throw Error('وصلت لعدد البريكات المسموح في الوردية');const b={id:crypto.randomUUID(),employeeId:id,name:p.name,branch:p.branch,punchId:p.id,start:new Date().toISOString(),end:null,allowedMinutes:db.rules.breakMinutes,source,reason,rule:structuredClone(db.rules)};db.breaks.push(b);audit('بدء بريك: '+p.name+(source==='manual'?' — إداري: '+reason:''));return b}
function endBreak(id,source='employee',reason=''){const b=activeBreak(id);if(!b)throw Error('لا يوجد بريك مفتوح');b.end=new Date().toISOString();b.closedBy=source;b.closeReason=reason;settleBreak(b);audit('إنهاء بريك: '+b.name+(source==='manual'?' — إداري: '+reason:''));return b}
function scoreCards(id){const s=scoreSummary(id);return `<div class="score-pair"><div class="score-box positive"><span>● نقاط الالتزام</span><strong>${s.green}</strong><small>متاح ${s.available} نقطة بعد إلغاء الجزاءات</small></div><div class="score-box negative"><span>● نقاط المخالفات</span><strong>${s.red}</strong><small>ملغي ${s.cancelled} • متبقي ${s.remaining}</small></div></div><p class="score-explain">كل ${s.ratio} نقطة خضرا تلغي نقطة حمرا. السجل تراكمي ولا يتم مسح المخالفة الأصلية. النقاط ليست خصمًا ماليًا.</p>`}
function breakStatus(b){const minutes=breakDuration(b),over=breakOverrun(b);return `<span class="badge ${over>0?'amber':''}">${b.end?'انتهى':'جاري'} • ${Math.floor(minutes)} دقيقة ${over>0?' / تجاوز '+Math.ceil(over)+' د':''}</span>`}
function breakPanel(s){const b=activeBreak(s.id),p=activePunch(s.id);return card('بريكي النهارده',`<div class="employee-hero"><h2>${b?'البريك شغال ☕':'وقت تركّز، ووقت ترتاح'}</h2><p>${db.rules.breakMinutes} دقيقة للبريك • ${db.rules.maxBreaks} بريك لكل وردية • سماح ${db.rules.graceMinutes} د</p>${b?`<strong id="breakTimer" data-start="${b.start}">${Math.max(0,Math.ceil(b.allowedMinutes-breakDuration(b)))}</strong><p>${breakStatus(b)}</p>`:''}<button class="primary" id="employeeBreak" ${!p?'disabled':''}>${b?'إنهاء البريك والعودة':'بدء البريك'}</button><p>${db.rules.enabled?'تجاوز المدة يحسب حسب نسخة اللائحة وقت بداية البريك':'اللائحة في وضع المسودة؛ يظهر التجاوز بدون جزاء تلقائي'}</p></div>`)}
function dateField(t,n,value=''){return `<label>${t}<input required type="datetime-local" name="${n}" value="${esc(value)}"></label>`}
function cairoInput(t=Date.now()){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Cairo',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(t));const p=Object.fromEntries(parts.map(p=>[p.type,p.value]));return `${p.year}-${p.month}-${p.day}T${p.hour}:${p.minute}`}
function cairoToISO(value){if(!/^\d{4}-\d\d-\d\dT\d\d:\d\d$/.test(value))throw Error('تاريخ غير صحيح');const target=Date.parse(value+'Z');let guess=target;for(let i=0;i<4;i++){const rendered=cairoInput(guess),diff=target-Date.parse(rendered+'Z');if(!diff){if(cairoInput(guess)!==value)throw Error('التوقيت غير موجود بالقاهرة');return new Date(guess).toISOString()}guess+=diff}throw Error('التوقيت غير صالح بتوقيت القاهرة')}
function safeSubmit(title,fields,action){openForm(title,fields,()=>{});$('#form').onsubmit=async e=>{e.preventDefault();try{await action(new FormData(e.target));save();$('#modal').close();render();toast('تم الحفظ في النسخة المحلية')}catch(err){toast(err.message)}}}
function manualAttendanceForm(editId=null){const existing=db.punches.find(p=>p.id===editId);const fields=`<p>الأوقات بتوقيت القاهرة. السجل اليدوي يظهر كتعديل إداري، بدون ادعاء التحقق من GPS.</p><label>الموظف${staffOptions('manualEmployee',false,existing?.employeeId)}</label>${dateField('الحضور','in',existing?cairoInput(existing.in):cairoInput())}<label>الانصراف (اختياري لوردية مفتوحة)<input type="datetime-local" name="out" value="${existing?.out?cairoInput(existing.out):''}"></label>${field('سبب التسجيل / التصحيح','reason')}`;safeSubmit(existing?'تصحيح سجل حضور':'إضافة حضور / انصراف يدوي',fields,f=>{const employeeId=Number(f.get('manualEmployee')),s=allEmployees().find(s=>s.id===employeeId);if(!f.get('reason').trim())throw Error('اكتب سبب واضح للتعديل');if(existing&&employeeId!==existing.employeeId)throw Error('لا يمكن نقل سجل حضور لموظف آخر');const input=cairoToISO(f.get('in')),out=f.get('out')?cairoToISO(f.get('out')):null;if(new Date(input)>new Date()||(out&&new Date(out)>new Date()))throw Error('لا يمكن تسجيل حضور أو انصراف في المستقبل');if(out&&new Date(out)<=new Date(input))throw Error('الانصراف لازم يكون بعد الحضور، حدد اليوم التالي لو وردية ليلية');if(activeBreak(employeeId))throw Error('أنهِ بريك الموظف قبل تعديل الحضور');const conflict=db.punches.find(p=>p.id!==editId&&p.employeeId===employeeId&&new Date(p.in).getTime()<(out?new Date(out).getTime():Infinity)&&(p.out?new Date(p.out).getTime():Infinity)>new Date(input).getTime());if(conflict)throw Error('التوقيت متداخل مع وردية موجودة؛ عدّل السجل الموجود');if(!existing&&db.punches.some(p=>p.employeeId===employeeId&&cairoDay(p.in)===cairoDay(input)))throw Error('يوجد سجل لنفس اليوم. استخدم تصحيح السجل لتجنب التكرار');if(existing&&db.breaks.some(b=>b.punchId===existing.id&&(new Date(b.start)<new Date(input)||(out&&b.end&&new Date(b.end)>new Date(out)))))throw Error('الفترة الجديدة لازم تشمل البريكات المسجلة');const next={employeeId,name:s.name,branch:s.branch,in:input,out,source:'manual',reason:f.get('reason').trim(),inLocation:{distance:'—',accuracy:'—'}};if(existing){existing.revisions??=[];existing.revisions.push({at:new Date().toISOString(),before:{in:existing.in,out:existing.out},reason:next.reason});Object.assign(existing,next)}else db.punches.push({id:Date.now(),...next});audit((existing?'تصحيح حضور: ':'حضور يدوي: ')+s.name+' — '+next.reason)})}
function manualOut(id){safeSubmit('تسجيل انصراف إداري',field('سبب الانصراف اليدوي','reason'),f=>{const p=activePunch(id);if(!p)throw Error('لا يوجد حضور مفتوح للموظف');if(!f.get('reason').trim())throw Error('اكتب سبب الانصراف');if(activeBreak(id))throw Error('أنهِ البريك قبل الانصراف');p.out=new Date().toISOString();p.outSource='manual';p.outReason=f.get('reason').trim();audit('انصراف إداري: '+p.name+' — '+p.outReason)})}
function manualBreakForm(){safeSubmit('إدارة بريك يدوي',`<label>الموظف${staffOptions('breakEmployee')}</label>${options('الحركة','action',['بدء بريك','إنهاء بريك'])}${field('السبب الإداري','reason')}`,f=>{const id=Number(f.get('breakEmployee')),reason=f.get('reason').trim();if(f.get('action')==='بدء بريك')startBreak(id,'manual',reason);else endBreak(id,'manual',reason)})}
function accountForm(existing=null){safeSubmit(existing?'تعديل الأكسس':'إنشاء بطاقة حساب',`<p>بطاقة إعداد محلية فقط؛ لا تنشئ حساب دخول أو ترسل دعوة. لن نطلب أو نخزن باسورد في المتصفح.</p>${field('الاسم','name','text',existing?.name||'')}${field('البريد الإلكتروني','email','email',existing?.email||'')}${options('نوع الحساب','type',['موظف','مدير فرع','موارد بشرية','مدير عام'])}<label>اربط بموظف${staffOptions('linkedEmployee',true,existing?.employeeId)}</label><h3>الفروع المسموحة</h3>${db.branches.map((b,i)=>`<label class="permission-item"><input type="checkbox" name="branch" value="${esc(b.name)}" ${existing?.branches.includes(b.name)?'checked':''}>${esc(b.name)}</label>`).join('')}<h3>الصلاحيات التفصيلية</h3><div class="permission-grid">${Object.entries(accessLabels).map(([k,t])=>`<label class="permission-item"><input type="checkbox" name="access" value="${k}" ${existing?.permissions.includes(k)?'checked':''}>${t}</label>`).join('')}</div>`,f=>{const email=f.get('email').trim().toLowerCase(),name=f.get('name').trim(),branches=f.getAll('branch'),permissions=f.getAll('access');if(!name)throw Error('اكتب الاسم');if(db.accounts.some(a=>a.email===email&&a.id!==existing?.id))throw Error('البريد مرتبط ببطاقة حساب بالفعل');if(!branches.length)throw Error('اختار فرع واحد على الأقل');const employeeId=f.get('linkedEmployee')?Number(f.get('linkedEmployee')):null;const payload={name,email,type:f.get('type'),branches,permissions,employeeId};if(existing)Object.assign(existing,payload);else db.accounts.push({id:crypto.randomUUID(),...payload,disabled:false,createdAt:new Date().toISOString(),provisioned:false});audit((existing?'تعديل أكسس: ':'إنشاء بطاقة حساب: ')+name)});if(existing)$('#fields select[name="type"]').value=existing.type;$('#linkedEmployee option[value=""]').textContent='بدون ربط بموظف'}
function managerRequestsAdminCard(){const rows=(db.managerRequests||[]);const pending=rows.filter(r=>r.status==='pending');const done=rows.filter(r=>r.status!=='pending').slice(-5).reverse();const row=r=>`<div class="request"><div class="details"><strong>${esc(r.name)}</strong><p>طلب أكسس مدير قسم ${esc(r.department)} — ${esc(r.branch)}<br><small>${esc(r.requestedAt||'')}</small>${r.reviewNote?`<br>سبب الرفض: ${esc(r.reviewNote)}`:''}${r.reviewedBy?`<br>راجعه: ${esc(r.reviewedBy)}`:''}</p></div>${r.status==='pending'?`<button data-mgr-approve="${r.id}">قبول الطلب</button><button class="reject" data-mgr-reject="${r.id}">رفض الطلب</button>`:badge(r.status==='approved'?'مقبول':'مرفوض')}</div>`;return card('طلبات أكسس مدراء الأقسام',(pending.map(row).join('')||'<p class="empty">لا توجد طلبات أكسس مدير بانتظار المراجعة</p>')+(done.length?`<h3 style="margin:14px 0 6px">آخر القرارات</h3>`+done.map(row).join(''):'')+'<p class="empty" style="margin-top:10px">القبول يفعّل أكسس مدير القسم ومهام قسمه بعد إعادة تسجيل دخوله. لا يتم منح أي أكسس تلقائيًا.</p>')}
function managerRequestReview(id,approved){const r=(db.managerRequests||[]).find(r=>String(r.id)===String(id));if(!r)return;safeSubmit((approved?'قبول':'رفض')+' طلب أكسس مدير — '+r.name,(approved?`<p>سيحصل ${esc(r.name)} على أكسس مدير قسم ${esc(r.department)} — ${esc(r.branch)} بعد إعادة تسجيل دخوله.</p>`:field('سبب الرفض','reason')),async f=>{if(typeof nodeUser!=='undefined'&&nodeUser&&nodeUser.role==='admin'){await nodeApi('manager-requests/'+id+'/review',{method:'POST',body:{approved,reason:f.get('reason')||''}});await refreshServerData();toast(approved?'تم تفعيل أكسس المدير':'تم رفض الطلب')}else{r.status=approved?'approved':'rejected';if(!approved)r.reviewNote=String(f.get('reason')||'');r.reviewedAt=new Date().toISOString();r.reviewedBy='الإدارة';audit((approved?'قبول':'رفض')+' طلب أكسس مدير: '+r.name)}})}
function branchAccessView(){const people=db.staff.filter(s=>!s.legacyProfileId||s.needsActivation!==true);const label=v=>v==='both'?'الفرعين':v==='any'?'أي فرع':'فرعه فقط';return card('أكسس تسجيل الحضور حسب الفرع',`<p class="empty" style="margin:0 0 12px">تحديد الفروع اللي يقدر كل موظف يسجل حضور منها. قيد المسافة (٨٠ متر) بيتطبق على كل فرع مسموح بيه على حدة. الافتراضي: فرعه فقط.</p><div class="table-wrap"><table><tr><th>الموظف</th><th>القسم</th><th>فرعه الأساسي</th><th>يسجل حضور من</th></tr>${people.map(s=>`<tr><td>${esc(s.name)}</td><td>${esc(s.department||s.job||'—')}</td><td>${esc(s.branch||'—')}</td><td><select data-branch-access="${s.id}">${['own','both','any'].map(v=>`<option value="${v}" ${(s.branchAccess||'own')===v?'selected':''}>${label(v)}</option>`).join('')}</select></td></tr>`).join('')}</table></div>${people.length?'':'<p class="empty">لا يوجد موظفون بعد</p>'}`)}
function accountsView(){return `<div class="notice">إعداد الحسابات والصلاحيات هنا للمعاينة فقط؛ الحسابات الفعلية وإنفاذ الأكسس يحتاجان خادم وتسجيل دخول. لا تدخل كلمات مرور.</div>`+card('إدارة الحسابات والأكسس',`<div class="table-wrap"><table><tr><th>الحساب</th><th>الدور</th><th>الفروع</th><th>الأكسس</th><th>حالة المعاينة</th><th>إدارة</th></tr>${db.accounts.map(a=>`<tr><td>${esc(a.name)}<br><small>${esc(a.email)}</small></td><td>${esc(a.type)}</td><td>${a.branches.map(esc).join('، ')}</td><td>${a.permissions.length} صلاحية</td><td>${badge(a.disabled?'موقوف محليًا':'إعداد غير مربوط بالدخول')}</td><td><button data-account-edit="${a.id}">تعديل</button><button data-account-toggle="${a.id}">${a.disabled?'استعادة':'إيقاف'}</button></td></tr>`).join('')}</table></div>${!db.accounts.length?'<p class="empty">أنشئ بطاقة حساب وحدد الفروع والصلاحيات</p>':''}`,'<button id="newAccount">＋ بطاقة حساب</button>')}

function openingBalanceCard(){const rows=(db.attendanceOpening||[]).slice().reverse();return card('رصيد الحضور الافتتاحي — قبل بدء التطبيق (للإدارة فقط)','<div class="toolbar"><button class="primary" id="newOpening">＋ إضافة رصيد افتتاحي</button></div><div class="table-wrap"><table><tr><th>الموظف</th><th>بداية الفترة</th><th>الشيفتات</th><th>ساعات الشيفت</th><th>إجمالي الساعات</th><th>السبب</th><th>آخر تعديل</th><th>إجراء</th></tr>'+rows.map(o=>'<tr><td>'+esc(o.employeeName)+'</td><td>'+esc(o.date)+'</td><td>'+o.shifts+'</td><td>'+o.hoursPerShift+'</td><td>'+Number(o.hours).toFixed(2)+'</td><td>'+esc(o.reason||'')+'</td><td><small>'+esc(o.updatedBy||o.createdBy||'')+'<br>'+stamp(o.updatedAt||o.createdAt)+'</small></td><td><button data-edit-opening="'+o.id+'">تصحيح</button> <button data-del-opening="'+o.id+'">حذف</button></td></tr>').join('')+'</table></div>'+(rows.length?'':'<p class="empty">لا توجد أرصدة افتتاحية — تُستخدم لإضافة حضور الأيام قبل بدء استخدام التطبيق في الشهر الحالي</p>')+'<p class="score-explain">الرصيد يدخل تلقائيًا في ساعات تقفيل المرتبات وتقرير الحضور للفترة التي يقع فيها التاريخ، وكل إضافة أو تعديل أو حذف يسجل باسم المستخدم والوقت في سجل التعديلات.</p>')}
function openingBalanceForm(editId=null){const existing=(db.attendanceOpening||[]).find(o=>String(o.id)===String(editId));const who=(nodeUser&&(nodeUser.email||nodeUser.name))||role;safeSubmit(existing?'تصحيح رصيد افتتاحي':'إضافة رصيد افتتاحي','<p>رصيد استثنائي لحضور أيام قبل بدء استخدام التطبيق. يظهر كسطر مستقل في التقفيلة والتقارير، ولا ينشئ سجل بصمة.</p><label>الموظف'+staffOptions('openingEmployee',false,existing?.employeeId)+'</label><label>تاريخ بداية الفترة<input required type="date" name="date" value="'+esc(existing?.date||cairoDay())+'"></label>'+field('عدد الشيفتات','shifts','number',existing?.shifts??'')+field('ساعات الشيفت الواحد','hoursPerShift','number',existing?.hoursPerShift??8)+field('السبب / ملاحظة','reason','text',existing?.reason||''),f=>{const employeeId=Number(f.get('openingEmployee')),s=allEmployees().find(x=>x.id===employeeId);if(!s)throw Error('اختار الموظف');const shifts=Number(f.get('shifts')),hoursPerShift=Number(f.get('hoursPerShift'));if(!Number.isInteger(shifts)||shifts<1||shifts>31)throw Error('عدد الشيفتات لازم يكون رقم صحيح من 1 لـ 31');if(!Number.isFinite(hoursPerShift)||hoursPerShift<1||hoursPerShift>16)throw Error('ساعات الشيفت من 1 لـ 16');const reason=String(f.get('reason')||'').trim();if(!reason)throw Error('اكتب سبب واضح');const date=String(f.get('date'));if(!/^\d{4}-\d\d-\d\d$/.test(date))throw Error('تاريخ غير صحيح');if(existing){existing.history??=[];existing.history.push({at:new Date().toISOString(),by:who,before:{date:existing.date,shifts:existing.shifts,hoursPerShift:existing.hoursPerShift,reason:existing.reason}});Object.assign(existing,{date,shifts,hoursPerShift,hours:shifts*hoursPerShift,reason,updatedBy:who,updatedAt:new Date().toISOString()});audit('تصحيح رصيد افتتاحي: '+s.name+' — '+reason)}else{db.attendanceOpening??=[];db.attendanceOpening.push({id:crypto.randomUUID(),employeeId,employeeName:s.name,branch:s.branch,date,shifts,hoursPerShift,hours:shifts*hoursPerShift,reason,createdBy:who,createdAt:new Date().toISOString(),history:[]});audit('رصيد افتتاحي: '+s.name+' — '+shifts+' شيفت — '+reason)}})}
function manualView(){return `<div class="notice">تدخل إداري استثنائي بسبب إلزامي، محفوظ في سجل التعديلات. يدعم اليوم القديم والوردية الممتدة لليوم التالي.</div>`+card('تحكم المدير في الحضور',`<div class="toolbar"><button class="primary" id="newManual">＋ حضور / تصحيح يوم</button><button id="newManualBreak">إدارة البريكات</button></div><div class="table-wrap"><table><tr><th>الموظف</th><th>الفرع</th><th>الحالة</th><th>إجراء</th></tr>${list().map(s=>`<tr><td>${esc(s.name)}</td><td>${esc(s.branch)}</td><td>${activeBreak(s.id)?badge('في بريك'):activePunch(s.id)?badge('حاضر'):'خارج الوردية'}</td><td><button data-now-out="${s.id}" ${!activePunch(s.id)?'disabled':''}>انصراف الآن</button></td></tr>`).join('')}</table></div>`)+card('تصحيح سجل موجود',`<div class="table-wrap"><table><tr><th>الموظف</th><th>بداية الوردية</th><th>نوع السجل</th><th>تعديل</th></tr>${db.punches.slice().reverse().map(p=>`<tr><td>${esc(p.name)}</td><td>${stamp(p.in)}</td><td>${p.source==='manual'?'يدوي إداري':'GPS'}</td><td><button data-edit-punch="${p.id}">تصحيح</button></td></tr>`).join('')}</table></div>`)+(role==='الإدارة'?openingBalanceCard():'')}
function breaksView(){return `<div class="notice">البريك ظاهر هنا وعند الموظف. الجزاء يحسب مرة واحدة عند إنهاء البريك حسب نسخة اللائحة وقت بدايته؛ المسودة لا تطبق جزاءات.</div>`+card('متابعة البريكات',`<div class="toolbar"><button id="newManualBreak">＋ بريك إداري</button></div><div class="table-wrap"><table><tr><th>الموظف</th><th>الفرع</th><th>البداية</th><th>النهاية</th><th>المسموح</th><th>الحالة</th><th>اللائحة</th></tr>${db.breaks.slice().reverse().map(b=>`<tr><td>${esc(b.name)}</td><td>${esc(b.branch)}</td><td>${stamp(b.start)}</td><td>${b.end?stamp(b.end):'مفتوح'}</td><td>${b.allowedMinutes} د</td><td>${breakStatus(b)}</td><td>v${b.rule.version} ${b.rule.enabled?'مفعلة':'مسودة'}</td></tr>`).join('')}</table></div>${!db.breaks.length?'<p class="empty">لا توجد بريكات حتى الآن</p>':''}`)}
function pointsView(){let employees=allEmployees();let s=employees.find(s=>String(s.id)===scoreEmployee)||employees[0];if(!s)return '<p class="empty">لا يوجد موظفون</p>';return card('رصيد الموظف',`<div class="toolbar">${staffOptions('scoreEmployee',false,s.id)}<button class="primary" id="newPoint">＋ نقطة التزام / مخالفة</button></div><div style="padding:0 22px 20px">${scoreCards(s.id)}</div>`)+card('سجل النقاط والتسويات',`<div class="table-wrap"><table><tr><th>الوقت</th><th>النوع</th><th>العدد</th><th>السبب</th><th>الحالة</th><th>إجراء</th></tr>${db.points.filter(p=>p.employeeId===s.id).slice().reverse().map(p=>`<tr><td>${stamp(p.at)}</td><td><span class="badge ${p.color==='red'?'point-red':''}">${p.color==='green'?'خضرا — التزام':'حمرا — مخالفة'}</span></td><td>${p.amount}</td><td style="white-space:normal;min-width:180px">${esc(p.reason)}</td><td>${p.voidedAt?'ملغاة: '+esc(p.voidReason):'مسجلة'}</td><td>${!p.voidedAt?`<button data-void-point="${p.id}">إلغاء بسبب</button>`:'—'}</td></tr>`).join('')}</table></div><p class="score-explain">إلغاء النقطة يحفظ أصلها وسبب الإلغاء. رصيد الإلغاء يعاد حسابه تلقائيًا بدون خصم مالي أو صرف.</p>`)}
function pointForm(){const s=$('#scoreEmployee')?.value;safeSubmit('تسجيل نقطة',`<label>الموظف${staffOptions('pointEmployee',false,s)}</label>${options('نوع النقطة','color',['خضرا — التزام','حمرا — مخالفة'])}${field('عدد النقاط','amount','number',1)}${field('السبب الواضح','reason')}`,f=>{const employeeId=Number(f.get('pointEmployee')),color=f.get('color').startsWith('خضرا')?'green':'red';addPoint({employeeId,color,amount:Number(f.get('amount')),reason:f.get('reason'),source:'manual:'+crypto.randomUUID()});audit('إضافة نقاط '+(color==='green'?'خضرا':'حمرا')+' للموظف '+allEmployees().find(s=>s.id===employeeId).name)})}
function rulesView(){const r=db.rules;return `<div class="notice">اللائحة الحالية ${r.enabled?'مفعلة محليًا':'مسودة غير مفعلة'} • الإصدار ${r.version}. القيم المعروضة اقتراح قابل للتعديل، وليست نقلًا للائحة جيمك المالية.</div>`+card('قواعد البريكات والتحفيز',`<form id="rulesForm" class="rules-form">${field('دقائق البريك الواحد','breakMinutes','number',r.breakMinutes)}${field('أقصى عدد بريكات في الوردية','maxBreaks','number',r.maxBreaks)}${field('دقائق السماح بعد مدة البريك','graceMinutes','number',r.graceMinutes)}${field('نقاط حمرا لكل بريك متجاوز (مرة واحدة)','redPerOverrun','number',r.redPerOverrun)}${field('عدد النقاط الخضرا لإلغاء نقطة حمرا','greenToCancel','number',r.greenToCancel)}<label class="permission-item"><input name="enabled" type="checkbox" ${r.enabled?'checked':''}>تفعيل جزاءات البريكات الجديدة</label><label class="permission-item"><input name="autoGreen" type="checkbox" ${r.autoGreen?'checked':''}>نقطة خضرا تلقائية للعودة في الموعد (مرة يوميًا، بريك موظف فقط)</label><p>التعديلات لا تغير جزاء البريكات القديمة. نسبة الإلغاء تطبق على الرصيد التراكمي الحالي. لا يوجد خصم نقدي تلقائي.</p><button class="primary">حفظ نسخة اللائحة</button></form>`)}
function reportRows(){return db.punches.filter(p=>(!reportFilter.from||cairoDay(p.in)>=reportFilter.from)&&(!reportFilter.to||cairoDay(p.in)<=reportFilter.to)&&(!reportFilter.employee||p.employeeId===Number(reportFilter.employee))&&(!reportFilter.branch||p.branch===reportFilter.branch))}
function netHours(p){if(!p.out)return null;return Math.max(0,(new Date(p.out)-new Date(p.in))/36e5)}
function reportView(){const rows=reportRows(),closed=rows.filter(p=>p.out),ids=new Set(rows.map(p=>p.employeeId)),breaks=db.breaks.filter(b=>rows.some(p=>p.id===b.punchId));const openingRows=(db.attendanceOpening||[]).filter(o=>(!reportFilter.from||o.date>=reportFilter.from)&&(!reportFilter.to||o.date<=reportFilter.to)&&(!reportFilter.employee||Number(o.employeeId)===Number(reportFilter.employee))&&(!reportFilter.branch||o.branch===reportFilter.branch)),openingRowsHTML=openingRows.length?'<h3>رصيد افتتاحي قبل التطبيق — مشمول في إجمالي الساعات</h3><div class="table-wrap"><table><tr><th>الموظف / الفرع</th><th>بداية الفترة</th><th>الشيفتات</th><th>ساعات الشيفت</th><th>الساعات</th><th>السبب / آخر تعديل</th></tr>'+openingRows.map(o=>'<tr><td>'+esc(o.employeeName)+'<br><small>'+esc(o.branch)+'</small></td><td>'+esc(o.date)+'</td><td>'+o.shifts+'</td><td>'+o.hoursPerShift+'</td><td>'+Number(o.hours).toFixed(2)+'</td><td>'+esc(o.reason||'')+'<br><small>'+esc(o.updatedBy||o.createdBy||'')+' • '+stamp(o.updatedAt||o.createdAt)+'</small></td></tr>').join('')+'</table></div>':'';return `<div class="notice no-print">التقرير مبني على السجلات الفعلية بالموقع أو اليدوية فقط، بدون بيانات الرسم التوضيحية. البريك مدفوع بالكامل ولا يخصم من الساعات؛ الوردية المفتوحة لا تدخل إجمالي الساعات.</div><div class="report-paper" id="reportPaper"><div class="report-brand"><div><b>ENERGY <span>STAFF</span></b><p>تقرير الحضور والأداء الوظيفي</p></div><div>نسخة تجريبية محلية<br><small>صادر: ${stamp(new Date().toISOString())}</small></div></div><form id="reportFilters" class="toolbar no-print"><label>من<input type="date" name="from" value="${reportFilter.from}"></label><label>إلى<input type="date" name="to" value="${reportFilter.to}"></label><label>الموظف${staffOptions('reportEmployee',true,reportFilter.employee)}</label><label>الفرع<select name="branch"><option value="">كل الفروع</option>${db.branches.map(b=>`<option value="${esc(b.name)}" ${reportFilter.branch===b.name?'selected':''}>${esc(b.name)}</option>`).join('')}</select></label><button class="primary">عرض التقرير</button></form><p class="report-period">الفترة: ${reportFilter.from||'كل السجلات'} — ${reportFilter.to||'حتى الآن'} • ${reportFilter.branch||'كل الفروع'}</p><div class="report-kpis"><div><span>الموظفون في التقرير</span><b>${ids.size}</b></div><div><span>ورديات مغلقة / مفتوحة</span><b>${closed.length} / ${rows.length-closed.length}</b></div><div><span>ساعات الحضور المدفوعة${openingRows.length?' (شاملة الرصيد الافتتاحي)':''}</span><b>${(closed.reduce((s,p)=>s+netHours(p),0)+openingRows.reduce((s,o)=>s+Number(o.hours||0),0)).toFixed(2)}</b></div><div><span>بريكات متجاوزة</span><b>${breaks.filter(b=>breakOverrun(b)>0).length}</b></div></div><div class="table-wrap"><table><thead><tr><th>الموظف / الفرع</th><th>الحضور</th><th>الانصراف</th><th>الساعات الإجمالية</th><th>الساعات المدفوعة</th><th>المصدر</th></tr></thead><tbody>${rows.slice().reverse().map(p=>`<tr><td>${esc(p.name)}<br><small>${esc(p.branch)}</small></td><td>${stamp(p.in)}</td><td>${p.out?stamp(p.out):'مفتوحة'}</td><td>${p.out?((new Date(p.out)-new Date(p.in))/36e5).toFixed(2):'—'}</td><td>${p.out?netHours(p).toFixed(2):'—'}</td><td>${p.source==='manual'?'إداري':'GPS'}</td></tr>`).join('')}</tbody></table></div>${openingRowsHTML}${!rows.length?'<p class="empty">لا توجد سجلات للفترة المختارة</p>':''}<h3>تفاصيل البريكات</h3><div class="table-wrap"><table><tr><th>الموظف</th><th>البداية</th><th>المدة</th><th>المسموح</th><th>التجاوز</th></tr>${breaks.map(b=>`<tr><td>${esc(b.name)}</td><td>${stamp(b.start)}</td><td>${Math.ceil(breakDuration(b))} د ${b.end?'':'(مفتوح)'}</td><td>${b.allowedMinutes} د</td><td>${Math.ceil(breakOverrun(b))} د</td></tr>`).join('')}</table></div><div class="report-signatures"><span>الموارد البشرية<br>________________</span><span>مدير الفرع<br>________________</span><span>اعتماد الإدارة<br>________________</span></div><p class="report-disclaimer">الأوقات بتوقيت القاهرة • التقرير محلي وليس اعتمادًا لصرف المرتبات. اللائحة المالية والأكسس الفعلي غير مربوطين بخادم بعد.</p></div><div class="toolbar no-print"><button class="primary" id="printReport">طباعة / حفظ PDF</button><button id="reportCSV">↓ تصدير CSV</button></div>`}
function csvReport(){const safe=v=>'"'+String(v).replace(/^[=+@-]/,' $&').replace(/"/g,'""')+'"';const rows=[['الموظف','الفرع','الحضور بالقاهرة','الانصراف بالقاهرة','ساعات الحضور شاملة البريك','المصدر'],...reportRows().map(p=>[p.name,p.branch,stamp(p.in),p.out?stamp(p.out):'مفتوح',p.out?netHours(p).toFixed(2):'',p.source==='manual'?'إداري':'GPS']),...(db.attendanceOpening||[]).filter(o=>(!reportFilter.from||o.date>=reportFilter.from)&&(!reportFilter.to||o.date<=reportFilter.to)&&(!reportFilter.employee||Number(o.employeeId)===Number(reportFilter.employee))&&(!reportFilter.branch||o.branch===reportFilter.branch)).map(o=>[o.employeeName,o.branch,'رصيد افتتاحي — '+o.date,'—',Number(o.hours).toFixed(2),'رصيد افتتاحي إداري'])];const blob=new Blob(['\ufeff'+rows.map(r=>r.map(safe).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Energy-Staff-Report.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
render=function(){operationRender();if(role==='الإدارة')$('#add').onclick=defaultAdminAdd;$('#add').hidden=false;$('#add').textContent=role==='الموظف'?'＋ طلب استثنائي':page==='accounts'?'＋ بطاقة حساب':'＋ إضافة موظف';if(role==='الموظف'){const s=currentEmployee();if(!s)return;$('#app').insertAdjacentHTML('beforeend',breakPanel(s)+card('التزامك بيعمل فرق',`<div style="padding:20px">${scoreCards(s.id)}<h3>آخر النقاط</h3>${db.points.filter(p=>p.employeeId===s.id).slice(-5).reverse().map(p=>`<div class="request"><span class="badge ${p.color==='red'?'point-red':''}">${p.amount} ${p.color==='green'?'خضرا':'حمرا'}</span><p>${esc(p.reason)}${p.voidedAt?' — ملغاة':''}</p></div>`).join('')}</div>`));$('#employeeBreak').onclick=async()=>{try{if(activeBreak(s.id))await endBreak(s.id);else await startBreak(s.id);render();toast('تم تحديث البريك')}catch(e){toast(e.message)}};$('#geoPunch').onclick=null;$('#geoPunch').replaceWith($('#geoPunch').cloneNode(true));$('#geoPunch').onclick=()=>{if(activeBreak(s.id))return toast('أنهِ البريك قبل تسجيل الانصراف');punch()};
const myCaptainClasses=(db.classes||[]).filter(c=>c.active!==false&&Number(c.captainStaffId)===Number(s.id));
let crb=$('#classRegister');if(!crb&&$('#geoPunch')){crb=document.createElement('button');crb.id='classRegister';crb.className=$('#geoPunch').className;$('#geoPunch').after(crb)}
if(crb){if(!myCaptainClasses.length){crb.hidden=true}else{crb.hidden=false;crb.textContent='＋ تسجيل كلاس';crb.onclick=()=>classRegisterSelf(myCaptainClasses)}}
let ces=$('#classEarningsSelf');if(!ces&&crb){ces=document.createElement('p');ces.id='classEarningsSelf';ces.className='empty';crb.after(ces)}
if(ces){const cm=new Date().toLocaleDateString('en-CA',{timeZone:'Africa/Cairo'}).slice(0,7);const myLogs=(db.classLogs||[]).filter(l=>l.source==='self'&&Number(l.captainStaffId)===Number(s.id)&&l.day&&String(l.day).startsWith(cm));const tot=myLogs.reduce((a,l)=>a+(Number(l.credited)||0),0);ces.textContent=myCaptainClasses.length?`مستحقاتك من الكلاسات الشهر ده (معاينة): ${myLogs.length} كلاس — ${tot} ج`:''}
return}
if(page==='branch-access'){$('#add').hidden=true;if(role!=='الإدارة'){$('#app').innerHTML='<p class="empty">صفحة خاصة بالإدارة</p>';return}$('#app').innerHTML=branchAccessView();document.querySelectorAll('[data-branch-access]').forEach(sel=>sel.onchange=()=>{const s=db.staff.find(x=>String(x.id)===sel.dataset.branchAccess);if(!s)return;s.branchAccess=sel.value;audit('أكسس حضور '+(sel.value==='own'?'فرعه فقط':sel.value==='both'?'الفرعين':'أي فرع')+': '+s.name);save();toast('تم حفظ أكسس الحضور لـ '+s.name)})}
if(page==='accounts'){$('#app').innerHTML=managerRequestsAdminCard()+accountsView();document.querySelectorAll('[data-mgr-approve]').forEach(b=>b.onclick=()=>managerRequestReview(b.dataset.mgrApprove,true));document.querySelectorAll('[data-mgr-reject]').forEach(b=>b.onclick=()=>managerRequestReview(b.dataset.mgrReject,false));$('#add').onclick=()=>accountForm();$('#newAccount').onclick=()=>accountForm();document.querySelectorAll('[data-account-edit]').forEach(b=>b.onclick=()=>accountForm(db.accounts.find(a=>a.id===b.dataset.accountEdit)));document.querySelectorAll('[data-account-toggle]').forEach(b=>b.onclick=()=>{const a=db.accounts.find(a=>a.id===b.dataset.accountToggle);a.disabled=!a.disabled;audit((a.disabled?'إيقاف':'استعادة')+' بطاقة حساب '+a.name);render()})}
if(page==='manual'){$('#app').innerHTML=manualView();$('#newManual').onclick=()=>manualAttendanceForm();document.querySelectorAll('[data-now-out]').forEach(b=>b.onclick=()=>manualOut(Number(b.dataset.nowOut)));document.querySelectorAll('[data-edit-punch]').forEach(b=>b.onclick=()=>manualAttendanceForm(Number(b.dataset.editPunch)));$('#newOpening')?.addEventListener('click',()=>openingBalanceForm());document.querySelectorAll('[data-edit-opening]').forEach(b=>b.onclick=()=>openingBalanceForm(b.dataset.editOpening));document.querySelectorAll('[data-del-opening]').forEach(b=>b.onclick=()=>{const o=(db.attendanceOpening||[]).find(x=>String(x.id)===String(b.dataset.delOpening));if(!o||!confirm('حذف الرصيد الافتتاحي لـ '+o.employeeName+'؟'))return;db.attendanceOpening=db.attendanceOpening.filter(x=>x!==o);audit('حذف رصيد افتتاحي: '+o.employeeName);save();render()})}
if(page==='breaks')$('#app').innerHTML=breaksView();$('#newManualBreak')?.addEventListener('click',manualBreakForm);
if(page==='score'){$('#app').innerHTML=pointsView();$('#scoreEmployee')?.addEventListener('change',e=>{scoreEmployee=e.target.value;render()});$('#newPoint')?.addEventListener('click',pointForm);document.querySelectorAll('[data-void-point]').forEach(b=>b.onclick=()=>safeSubmit('إلغاء نقطة مع الاحتفاظ بالسجل',field('سبب الإلغاء','reason'),f=>{const p=db.points.find(p=>p.id===b.dataset.voidPoint);if(p.voidedAt)throw Error('النقطة ملغاة بالفعل');p.voidedAt=new Date().toISOString();p.voidReason=f.get('reason').trim();audit('إلغاء نقطة '+p.id+' — '+p.voidReason)}))}
if(page==='rules'){$('#app').innerHTML=rulesView();$('#rulesForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),next={};for(const k of ['breakMinutes','maxBreaks','graceMinutes','redPerOverrun','greenToCancel']){next[k]=Number(f.get(k));if(!Number.isInteger(next[k])||next[k]<(k==='graceMinutes'?0:1)||next[k]>1440)return toast('استخدم أعدادًا صحيحة موجبة، والسماح ممكن صفر')}next.enabled=f.has('enabled');next.autoGreen=f.has('autoGreen');if(next.greenToCancel!==db.rules.greenToCancel&&!confirm('تغيير نسبة الإلغاء يعيد حساب الرصيد الحالي لكل الموظفين. متابعة؟'))return;db.ruleVersions.push({at:new Date().toISOString(),before:structuredClone(db.rules)});db.rules={...next,version:db.rules.version+1};audit('حفظ نسخة لائحة v'+db.rules.version);render();toast('تم حفظ اللائحة؛ البريكات الجديدة تتبع الإصدار الجديد')}}
if(page==='reports'){$('#app').innerHTML=reportView();$('#reportFilters').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(f.get('from')&&f.get('to')&&f.get('from')>f.get('to'))return toast('تاريخ البداية لازم يسبق النهاية');reportFilter={from:f.get('from'),to:f.get('to'),employee:f.get('reportEmployee'),branch:f.get('branch')};render()};$('#printReport').onclick=()=>{document.body.classList.add('printing-report');window.print()};$('#reportCSV').onclick=csvReport}

};
window.addEventListener('afterprint',()=>document.body.classList.remove('printing-report'));
setInterval(()=>{if(page==='breaks'||(role==='الموظف'&&activeBreak(currentEmployee()?.id))){const modal=$('#modal');if(!modal.open)render()}},15000);
render();
